            if color != bg and end - c >= 2:
                bars.append(((r, (c + end - 1) // 2), (dr, 0), color))
            c = end
    for c, dc in ((0, 1), (w - 1, -1)):
        r = 0
        while r < h:
            color = grid[r][c]
            end = r + 1
            while end < h and grid[end][c] == color: end += 1
            if color != bg and end - r >= 2:
                bars.append((((r + end - 1) // 2, c), (0, dc), color))
            r = end
    bar_colors = {color for _, _, color in bars}
    ray_colors = [v for v in flat if v != bg and v not in bar_colors]
    if not ray_colors:
        return out
    ray = ray_colors[0]
    for (r, c), (dr, dc), _ in bars:
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == ray:
                out[rr][cc] = 4
                break
            if grid[rr][cc] != bg:
                break
            out[rr][cc] = ray
